ALTER TABLE public.lessons ADD COLUMN owner_id uuid, ADD COLUMN transcript_status text NOT NULL DEFAULT 'sample';
GRANT INSERT, UPDATE ON public.lessons TO authenticated;
CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY lesson_owner_insert ON public.lessons FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY lesson_owner_update ON public.lessons FOR UPDATE TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
GRANT INSERT, UPDATE, DELETE ON public.transcript_chunks,public.topic_markers,public.quiz_questions TO authenticated;
CREATE POLICY chunk_owner ON public.transcript_chunks FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND (l.owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')))) WITH CHECK(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND (l.owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY marker_owner ON public.topic_markers FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND (l.owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')))) WITH CHECK(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND (l.owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY quiz_owner ON public.quiz_questions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND (l.owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')))) WITH CHECK(EXISTS(SELECT 1 FROM public.lessons l WHERE l.id=lesson_id AND (l.owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
REVOKE SELECT ON public.quiz_questions FROM anon,authenticated;
GRANT SELECT(id,lesson_id,topic_marker_id,question,options,source_start_sec) ON public.quiz_questions TO anon,authenticated;
ALTER TABLE public.quiz_attempts ADD COLUMN request_id uuid UNIQUE;
REVOKE INSERT ON public.quiz_attempts FROM authenticated;
CREATE FUNCTION public.submit_quiz(_question uuid,_pick int,_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quiz_questions; old public.quiz_attempts; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to practice'; END IF; SELECT * INTO q FROM quiz_questions WHERE id=_question; IF q.id IS NULL THEN RAISE EXCEPTION 'Question not found'; END IF; IF _pick<0 OR _pick>=jsonb_array_length(q.options) THEN RAISE EXCEPTION 'Invalid answer'; END IF; SELECT * INTO old FROM quiz_attempts WHERE request_id=_request; IF old.id IS NOT NULL AND (old.user_id<>auth.uid() OR old.question_id<>_question) THEN RAISE EXCEPTION 'Invalid request'; END IF; INSERT INTO quiz_attempts(user_id,question_id,correct,request_id) VALUES(auth.uid(),q.id,_pick=q.answer_index,_request) ON CONFLICT(request_id) DO NOTHING; RETURN jsonb_build_object('correct',_pick=q.answer_index,'answer_index',q.answer_index,'explanation',q.explanation); END $$;
REVOKE ALL ON FUNCTION public.submit_quiz FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_quiz TO authenticated;
CREATE OR REPLACE FUNCTION public.quiz_attempt_to_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m uuid; BEGIN SELECT topic_marker_id INTO m FROM quiz_questions WHERE id=new.question_id; IF m IS NULL THEN RETURN new; END IF; IF NOT new.correct THEN INSERT INTO revision_items(user_id,topic_marker_id,ease,interval_days,due_at,last_result) VALUES(new.user_id,m,2.3,0,now(),'wrong') ON CONFLICT(user_id,topic_marker_id) DO UPDATE SET ease=greatest(1.3,revision_items.ease-0.2),interval_days=0,due_at=now(),last_result='wrong'; ELSE INSERT INTO revision_items(user_id,topic_marker_id,interval_days,due_at,last_result) VALUES(new.user_id,m,1,now()+interval '1 day','correct') ON CONFLICT(user_id,topic_marker_id) DO UPDATE SET interval_days=CASE WHEN revision_items.interval_days=0 THEN 1 WHEN revision_items.interval_days=1 THEN 6 ELSE greatest(revision_items.interval_days+1,round(revision_items.interval_days*revision_items.ease)::int) END,due_at=now()+make_interval(days=>CASE WHEN revision_items.interval_days=0 THEN 1 WHEN revision_items.interval_days=1 THEN 6 ELSE greatest(revision_items.interval_days+1,round(revision_items.interval_days*revision_items.ease)::int) END),last_result='correct'; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.match_chunks(_lesson uuid,_query text,_upto int,_limit int DEFAULT 4) RETURNS TABLE(id uuid,start_sec int,end_sec int,text text,rank real) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT c.id,c.start_sec,c.end_sec,c.text,ts_rank(c.tsv,to_tsquery('english',_query)) FROM transcript_chunks c WHERE c.lesson_id=_lesson AND c.end_sec<=_upto AND c.tsv@@to_tsquery('english',_query) ORDER BY ts_rank(c.tsv,to_tsquery('english',_query)) DESC LIMIT least(_limit,8) $$;
CREATE TABLE public.interview_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),lesson_id uuid NOT NULL REFERENCES public.lessons(id),status text NOT NULL DEFAULT 'active',scorecard jsonb,questions jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.interview_sessions TO authenticated; GRANT ALL ON public.interview_sessions TO service_role;
ALTER TABLE public.interview_sessions ENABLE ROW LEVEL SECURITY; CREATE POLICY own_interview ON public.interview_sessions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.interview_turns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.interview_sessions(id) ON DELETE CASCADE,turn_index int NOT NULL,question text NOT NULL,answer text NOT NULL,evidence jsonb NOT NULL DEFAULT '[]',score jsonb NOT NULL DEFAULT '{}',UNIQUE(session_id,turn_index));
GRANT SELECT,INSERT ON public.interview_turns TO authenticated; GRANT ALL ON public.interview_turns TO service_role;
ALTER TABLE public.interview_turns ENABLE ROW LEVEL SECURITY; CREATE POLICY own_turn ON public.interview_turns FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid()));
CREATE TABLE public.shared_scorecards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),session_id uuid NOT NULL REFERENCES public.interview_sessions(id) ON DELETE CASCADE UNIQUE,token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.shared_scorecards TO authenticated; GRANT ALL ON public.shared_scorecards TO service_role;
ALTER TABLE public.shared_scorecards ENABLE ROW LEVEL SECURITY; CREATE POLICY own_share ON public.shared_scorecards FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.id=session_id AND s.user_id=auth.uid() AND s.status='complete'));
CREATE FUNCTION public.read_scorecard(_token uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('title',l.title,'scorecard',s.scorecard,'created_at',s.created_at) FROM shared_scorecards sh JOIN interview_sessions s ON s.id=sh.session_id JOIN lessons l ON l.id=s.lesson_id WHERE sh.token=_token AND s.status='complete' $$;
REVOKE ALL ON FUNCTION public.read_scorecard FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.read_scorecard TO anon,authenticated;
CREATE TABLE public.explanation_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),lesson_id uuid NOT NULL REFERENCES public.lessons(id),topic_marker_id uuid NOT NULL REFERENCES public.topic_markers(id),answer text NOT NULL,feedback jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.explanation_attempts TO authenticated; GRANT ALL ON public.explanation_attempts TO service_role;
ALTER TABLE public.explanation_attempts ENABLE ROW LEVEL SECURITY; CREATE POLICY own_explanation ON public.explanation_attempts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.ai_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.ai_requests TO authenticated; GRANT ALL ON public.ai_requests TO service_role;
ALTER TABLE public.ai_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY own_ai_request ON public.ai_requests FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.reserve_ai_request() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF (SELECT count(*) FROM ai_requests WHERE user_id=auth.uid() AND created_at>now()-interval '10 minutes')>=20 THEN RAISE EXCEPTION 'You have reached 20 AI requests in 10 minutes. Please wait.'; END IF; INSERT INTO ai_requests(user_id) VALUES(auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.reserve_ai_request FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_ai_request TO authenticated;
CREATE TABLE public.ai_access_state(id text PRIMARY KEY,status int NOT NULL,message text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_access_state TO service_role;
ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.replace_lesson_content(_lesson uuid,_title text,_youtube text,_source text,_chunks jsonb,_generated jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE lid uuid; m jsonb; q jsonb; mid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _lesson IS NULL THEN INSERT INTO lessons(title,youtube_id,source,owner_id,transcript_status,duration_sec,summary,note) VALUES(_title,_youtube,_source,auth.uid(),'provided',(SELECT max((c->>'end_sec')::int) FROM jsonb_array_elements(_chunks)c),_generated->>'summary',_generated->>'summary') RETURNING id INTO lid; ELSE SELECT id INTO lid FROM lessons WHERE id=_lesson AND (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')); IF lid IS NULL THEN RAISE EXCEPTION 'Only the lesson owner or an admin can replace this transcript'; END IF; UPDATE lessons SET transcript_status='provided',summary=_generated->>'summary',note=_generated->>'summary',duration_sec=(SELECT max((c->>'end_sec')::int) FROM jsonb_array_elements(_chunks)c) WHERE id=lid; DELETE FROM quiz_questions WHERE lesson_id=lid; DELETE FROM topic_markers WHERE lesson_id=lid; DELETE FROM transcript_chunks WHERE lesson_id=lid; END IF; INSERT INTO transcript_chunks(lesson_id,start_sec,end_sec,text) SELECT lid,(c->>'start_sec')::int,(c->>'end_sec')::int,c->>'text' FROM jsonb_array_elements(_chunks)c; FOR m IN SELECT * FROM jsonb_array_elements(_generated->'markers') LOOP INSERT INTO topic_markers(lesson_id,start_sec,title,summary) VALUES(lid,(m->>'start_sec')::int,m->>'title',m->>'summary'); END LOOP; FOR q IN SELECT * FROM jsonb_array_elements(_generated->'questions') LOOP SELECT id INTO mid FROM topic_markers WHERE lesson_id=lid AND start_sec<=(q->>'source_start_sec')::int ORDER BY start_sec DESC LIMIT 1; INSERT INTO quiz_questions(lesson_id,topic_marker_id,question,options,answer_index,explanation,source_start_sec) VALUES(lid,mid,q->>'question',q->'options',(q->>'answer_index')::int,q->>'explanation',(q->>'source_start_sec')::int); END LOOP; RETURN lid; END $$;
REVOKE ALL ON FUNCTION public.replace_lesson_content FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.replace_lesson_content TO authenticated;